begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n),'is_anonymous',false)::text,true)$$;
create function pg_temp.ctx(b integer default 101) returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(b))$$;
create function pg_temp.po(ident integer default 800) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('purchaseOrderId',pg_temp.i(ident),'supplierId',pg_temp.i(701),'reference','TEST-PO-'||ident,'expectedOn','2026-11-01','reason','TEST requested ten sacks','items',jsonb_build_array(jsonb_build_object('lineId',pg_temp.i(ident+100),'productId',pg_temp.i(301),'unitId',pg_temp.i(401),'quantity','10')))$$;
create function pg_temp.decision(ident integer default 810,outcome text default 'approve',state text default 'pending',orderid integer default 800) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('purchaseOrderId',pg_temp.i(orderid),'orderEventId',pg_temp.i(ident),'expectedState',state,'outcome',outcome,'reason','TEST owner verified purchase order')$$;
create function pg_temp.delivery(ident integer,accepted text default '0',held text default '0',rejected text default '10',document text default '10') returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(ident),'purchaseOrderId',pg_temp.i(800),'supplierId',pg_temp.i(701),'reference','TEST-INV-'||ident,'reason','TEST inspected supplier goods','items',jsonb_build_array(jsonb_build_object('orderLineId',pg_temp.i(900),'productId',pg_temp.i(301),'unitId',pg_temp.i(401),'documentQuantity',document,'accepted',accepted,'held',held,'rejected',rejected,'reason','TEST broken packaging and missing sacks')))$$;
create function pg_temp.work() returns jsonb language sql as $$select public.agri_command('purchasing_workspace',pg_temp.ctx())$$;
create function pg_temp.stock() returns numeric language sql as $$select quantity from public.branch_inventory where organization_id=pg_temp.i(1) and branch_id=pg_temp.i(101) and product_id=pg_temp.i(301) and batch_id is null$$;
create function pg_temp.claim(ident integer,outcome text default 'progress',version integer default 0) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(821),'claimEventId',pg_temp.i(ident),'expectedVersion',version,'outcome',outcome,'reference','TEST supplier credit CN-021','reason','TEST supplier evidence retained')$$;
create temporary table saved_requests(name text primary key,data jsonb);grant all on saved_requests to authenticated;
create function pg_temp.plan(receipt integer) returns jsonb language sql as $$select public.agri_command('delivery_reversal_check',pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(receipt)))$$;
create function pg_temp.rev(receipt integer,ident integer) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(receipt),'reversalId',pg_temp.i(ident),'expectedLedgerRevision',pg_temp.plan(receipt)->>'ledgerRevision','expectedOrderVersion',pg_temp.plan(receipt)->'orderVersion','reference','TEST signed correction sheet','reason','TEST owner verified mistaken entry and actual goods','physicalConfirmed',true,'queuesConfirmed',true)$$;
create function pg_temp.unplanned(ident integer,quantity text default '0.5',held text default '0') returns jsonb language sql as $$select pg_temp.delivery(ident,quantity,held,'0',(quantity::numeric+held::numeric)::text)||jsonb_build_object('purchaseOrderId',null,'items',jsonb_build_array((pg_temp.delivery(ident,quantity,held,'0',(quantity::numeric+held::numeric)::text)->'items'->0)||jsonb_build_object('orderLineId',null)))$$;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('create_purchase_order',pg_temp.po());select public.agri_command('purchase_order_event',pg_temp.decision());
select public.agri_command('inspect_delivery',pg_temp.delivery(821,'6','1','2'));
select public.agri_command('reverse_delivery',(select data from saved_requests where name='reverseCorrection'));
select public.agri_command('inspect_delivery',pg_temp.delivery(863,'2','0','0','2')||jsonb_build_object('correctsInspectionId',pg_temp.i(860),'expectedReversalId',pg_temp.i(862)));
-- Close an order, then reverse its untouched receiving: reopen by an appended decision.
select public.agri_command('create_purchase_order',pg_temp.po(870));select public.agri_command('purchase_order_event',pg_temp.decision(871,'approve','pending',870));
select public.agri_command('inspect_delivery',pg_temp.delivery(872,'10','0','0','10')||jsonb_build_object('purchaseOrderId',pg_temp.i(870),'items',jsonb_build_array((pg_temp.delivery(872,'10','0','0','10')->'items'->0)||jsonb_build_object('orderLineId',pg_temp.i(970)))));
select public.agri_command('purchase_order_event',pg_temp.decision(873,'close','approve',870));
select public.agri_command('reverse_delivery',pg_temp.rev(872,874));
select public.agri_command('inspect_delivery',pg_temp.delivery(875)||jsonb_build_object('purchaseOrderId',pg_temp.i(870),'items',jsonb_build_array((pg_temp.delivery(875)->'items'->0)||jsonb_build_object('orderLineId',pg_temp.i(970)))));
select public.agri_command('purchase_order_event',pg_temp.decision(876,'close','approve',870));
select public.agri_command('reverse_delivery',pg_temp.rev(875,877));
-- A partly closed order must retain its cancelled remainder; no automatic reopen.
select public.agri_command('create_purchase_order',pg_temp.po(910));select public.agri_command('purchase_order_event',pg_temp.decision(911,'approve','pending',910));
select public.agri_command('inspect_delivery',pg_temp.delivery(912,'1','0','0','1')||jsonb_build_object('purchaseOrderId',pg_temp.i(910),'items',jsonb_build_array((pg_temp.delivery(912,'1','0','0','1')->'items'->0)||jsonb_build_object('orderLineId',pg_temp.i(1010)))));
select public.agri_command('purchase_order_event',pg_temp.decision(913,'close','approve',910));
-- Subsequent activity blocks the complete operation, even if net stock looks sufficient.
select public.agri_command('inspect_delivery',pg_temp.unplanned(880));
reset role;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('inspect_delivery',pg_temp.unplanned(883,'0','1'));
select public.agri_command('disposition_hold',pg_temp.ctx()||jsonb_build_object('holdId',(select id from public.stock_holds where source_id=pg_temp.i(883)),'dispositionId',pg_temp.i(884),'quantity','1','disposition','supplier_return','reason','TEST real supplier return already occurred'));
select public.agri_command('inspect_delivery',pg_temp.unplanned(885,'1','1'));
select public.agri_command('record_delivery_claim',pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(885),'claimEventId',pg_temp.i(886),'expectedVersion',0,'outcome','progress','reference','TEST supplier contacted','reason','TEST existing supplier claim evidence'));
select public.agri_command('inspect_delivery',pg_temp.unplanned(887));
reset role;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('inspect_delivery',pg_temp.unplanned(889));
select public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'openingCash',0));
select public.agri_command('close_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'shiftId',(select id from public.cashier_shifts where branch_id=pg_temp.i(101) and closed_at is null),'countedCash',0));
reset role;
set local role authenticated;select pg_temp.login(11);
select pg_temp.login(12);
select pg_temp.login(13);
select pg_temp.login(14);
select pg_temp.login(15);
select pg_temp.login(11);
reset role;
do $$declare v_kind text;v_n integer:=0;v_id integer;v_before numeric;begin
 foreach v_kind in array array['transfer_out','transfer_in','purchase','refund','adjustment','loss','hold_out','hold_release'] loop
  v_n:=v_n+1;v_id:=10000+v_n;
  perform public.agri_command('inspect_delivery',pg_temp.unplanned(v_id));
  v_before:=pg_temp.stock();
 end loop;
end$$;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('inspect_delivery',pg_temp.unplanned(13000,'1','1')||jsonb_build_object('items',jsonb_build_array(pg_temp.unplanned(13000,'1','1')->'items'->0,jsonb_build_object('productId',pg_temp.i(303),'unitId',pg_temp.i(403),'documentQuantity','1','accepted','1','held','0','rejected','0','reason','TEST other product line'))));
reset role;
set local role authenticated;select pg_temp.login(11);
reset role;
delete from auth.sessions where user_id=pg_temp.i(11);
set local role authenticated;
reset role;insert into tap_results select * from finish();select line from tap_results;rollback;
